package com.plexus.personal.document.api;
import com.plexus.personal.auth.infrastructure.security.JwtAuthenticationWebFilter; import com.plexus.personal.document.application.DocumentService; import com.plexus.personal.document.application.KnowledgeSearchService; import org.springframework.http.MediaType; import org.springframework.web.bind.annotation.*; import org.springframework.http.codec.multipart.FilePart; import org.springframework.web.server.ServerWebExchange; import reactor.core.publisher.Mono; import java.util.*;
@RestController @RequestMapping("/api/documents") public class DocumentController {private final DocumentService service; private final KnowledgeSearchService search; public DocumentController(DocumentService s,KnowledgeSearchService k){service=s;search=k;} @GetMapping("/search") public List<java.util.Map<String,Object>> search(@RequestParam String q, @RequestParam(defaultValue="5") int limit, ServerWebExchange e){return search.search(uid(e),q,Math.min(limit,20));} @GetMapping public List<DocumentResponse> list(ServerWebExchange e){return service.list(uid(e)).stream().map(DocumentResponse::from).toList();} @GetMapping("/{id}") public DocumentResponse get(@PathVariable Long id,ServerWebExchange e){return DocumentResponse.from(service.find(id,uid(e)));} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) public Mono<DocumentResponse> upload(@RequestPart("file") FilePart f,ServerWebExchange e){return service.upload(uid(e),f).map(DocumentResponse::from);} @PostMapping("/{id}/reindex") public DocumentResponse reindex(@PathVariable Long id,ServerWebExchange e){service.reindex(id,uid(e));return DocumentResponse.from(service.find(id,uid(e)));} @DeleteMapping("/{id}") public void delete(@PathVariable Long id,ServerWebExchange e){service.delete(id,uid(e));} private Long uid(ServerWebExchange e){return Long.valueOf(e.getAttribute(JwtAuthenticationWebFilter.USER_ID_ATTRIBUTE));}}
